"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import {
  ArrowLeft, ArrowRight, BarChart3, Check, ChevronRight, CircleAlert, Copy,
  CreditCard, Gauge, Heart, HelpCircle, LayoutDashboard, LockKeyhole, MapPin,
  Package, RotateCcw, Search, Settings, ShieldCheck, ShoppingBag, Star, Tags,
  Truck, Users, Warehouse,
} from "lucide-react";
import { adminSections, products, routeMap, type Product } from "@/lib/catalog";
import {
  Button, CheckLine, Footer, Header, ProductGrid, ProductVisual,
  Quantity, Rating, SectionTitle, TrustStrip,
} from "@/components/store";
import { useShop, type CartSummary } from "@/components/shop-state";

const money=(cents:number)=>(cents/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});

type CatalogOption={id?:number;name?:string;slug?:string;size?:string;product_count:number;has_sizes?:number};
type FilterProduct={id:number;category_slug:string;brand_slug:string;price_cents:number;featured:number;sizes:string[];sizes_csv?:string};
type CatalogData={brands:CatalogOption[];categories:CatalogOption[];sizes:CatalogOption[];filter_products:FilterProduct[]};

const priceLimits=[500,750,1000,1500,3000];
function matchingProducts(catalog:CatalogData,filters:{category?:string;brand?:string;size?:string;maxPrice?:string}) {
  return catalog.filter_products.filter(product=>(!filters.category||product.category_slug===filters.category)&&(!filters.brand||product.brand_slug===filters.brand)&&(!filters.size||product.sizes.includes(filters.size))&&(!filters.maxPrice||product.price_cents<=Number(filters.maxPrice)*100));
}
function relevantPrices(productsIndex:FilterProduct[]) {
  return priceLimits.map(limit=>({limit,count:productsIndex.filter(product=>product.price_cents<=limit*100).length})).filter((item,index,items)=>item.count>0&&(index===0||item.count!==items[index-1].count));
}

function useCatalog() {
  const [catalog,setCatalog]=useState<CatalogData>({brands:[],categories:[],sizes:[],filter_products:[]});
  useEffect(()=>{const controller=new AbortController();fetch("/api/catalog",{signal:controller.signal}).then(r=>r.ok?r.json():Promise.reject()).then(({data})=>setCatalog({...data,filter_products:data.filter_products.map((product:FilterProduct)=>({...product,sizes:product.sizes_csv?product.sizes_csv.split("|"):[]}))})).catch(()=>{});return()=>controller.abort();},[]);
  return catalog;
}

export function StorePage({ path }: { path: string }) {
  if (path.startsWith("/admin")) return <AdminPage path={path}/>;
  if (path.startsWith("/checkout")) return <CheckoutPage path={path}/>;
  return <><Header/><main>{resolveStorePage(path)}</main><Footer/></>;
}

function useApiProducts(limit=12, query="") {
  const [items,setItems]=useState<Product[]>(products);
  useEffect(()=>{const controller=new AbortController();fetch(`/api/products?limit=${limit}${query}`,{signal:controller.signal}).then(r=>r.ok?r.json():Promise.reject()).then(({data})=>setItems(data.items.map((p:{id:number;slug:string;brand:string;name:string;price_cents:number;compare_at_cents?:number;image_url?:string;featured:number;photographer?:string;category?:string;sizes_csv?:string})=>({id:p.id,slug:p.slug,brand:p.brand,name:p.name,price:(p.price_cents/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}),oldPrice:p.compare_at_cents?(p.compare_at_cents/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}):undefined,tone:"from-zinc-950 to-zinc-700",tag:p.featured?"DESTAQUE":undefined,image:p.image_url,photographer:p.photographer,priceCents:p.price_cents,compareAtCents:p.compare_at_cents,category:p.category,sizes:p.sizes_csv?p.sizes_csv.split("|"):[]})))).catch(()=>{});return()=>controller.abort();},[limit,query]);
  return items;
}

function HomeHero({items}:{items:Product[]}) {
  const slides=items.filter(item=>item.image).slice(0,6);
  const [active,setActive]=useState(0);
  const [paused,setPaused]=useState(false);
  const total=slides.length;
  useEffect(()=>{if(paused||total<2)return;const timer=window.setInterval(()=>setActive(current=>(current+1)%total),5500);return()=>window.clearInterval(timer);},[paused,total]);
  useEffect(()=>{if(active>=total)setActive(0);},[active,total]);
  if(!total)return null;
  const current=slides[active];
  const hasSale=Boolean(current.compareAtCents);
  const go=(direction:number)=>setActive(index=>(index+direction+total)%total);
  return <section
    className="container-page relative mt-4 min-h-[540px] overflow-hidden rounded-3xl bg-dark text-white md:mt-0 md:min-h-[600px]"
    aria-roledescription="carrossel"
    aria-label="Ofertas em destaque"
    onMouseEnter={()=>setPaused(true)} onMouseLeave={()=>setPaused(false)}
    onFocusCapture={()=>setPaused(true)} onBlurCapture={()=>setPaused(false)}
  >
    {slides.map((slide,index)=><img key={slide.slug} src={slide.image} alt="" aria-hidden="true" className={`absolute inset-0 size-full object-cover transition-opacity duration-700 ${index===active?"opacity-100":"opacity-0"}`}/>)}
    <div className="absolute inset-0 bg-[linear-gradient(90deg,rgba(5,7,9,.94)_0%,rgba(5,7,9,.76)_42%,rgba(5,7,9,.18)_78%),linear-gradient(0deg,rgba(5,7,9,.72)_0%,transparent_52%)]"/>
    <div className="relative z-10 flex min-h-[540px] flex-col justify-end p-7 pb-24 md:min-h-[600px] md:justify-center md:p-14">
      <div key={current.slug} className="hero-content-in max-w-[680px]">
        <h1 className="max-w-2xl text-[40px] font-semibold uppercase leading-[.94] tracking-[-.05em] md:text-6xl">{hasSale?`${current.name} em condição especial`:`${current.brand} ${current.name}: pronto para a estrada`}</h1>
        <p className="mt-6 max-w-lg text-sm leading-6 text-[#d7dbe0] md:text-base">{hasSale?<><s className="mr-2 text-white/55">{current.oldPrice}</s><strong className="text-xl text-white">{current.price}</strong><span className="mt-1 block">ou 10x sem juros. Estoque sujeito à disponibilidade.</span></>:<><strong className="text-xl text-white">{current.price}</strong><span className="mt-1 block">Condição especial no Pix, envio rastreável e troca facilitada.</span></>}</p>
        <div className="mt-8 flex flex-wrap gap-3"><Button href={`/produto/${current.slug}`}>Ver produto <ArrowRight size={17}/></Button><Button href="/ofertas" variant="outline" className="border-white/30 bg-white/10 text-white hover:border-white hover:bg-white/20">Todas as ofertas</Button></div>
      </div>
    </div>
    <div className="absolute bottom-6 left-7 z-20 flex items-center gap-2 md:left-14">{slides.map((slide,index)=><button key={slide.slug} onClick={()=>setActive(index)} aria-label={`Ir para oferta ${index+1}`} aria-current={index===active?"true":undefined} className={`h-1.5 rounded-full transition-all ${index===active?"w-8 bg-accent":"w-3 bg-white/45 hover:bg-white"}`}/>)}</div>
    <div className="absolute bottom-5 right-6 z-20 flex gap-2 md:bottom-8 md:right-10"><button onClick={()=>go(-1)} aria-label="Oferta anterior" className="focus-ring grid size-11 place-items-center rounded-xl border border-white/20 bg-black/30 backdrop-blur-sm transition hover:bg-white hover:text-dark"><ArrowLeft size={18}/></button><button onClick={()=>go(1)} aria-label="Próxima oferta" className="focus-ring grid size-11 place-items-center rounded-xl border border-white/20 bg-black/30 backdrop-blur-sm transition hover:bg-white hover:text-dark"><ArrowRight size={18}/></button></div>
    {current.photographer&&<span className="absolute right-6 top-6 z-20 rounded bg-black/45 px-2 py-1 text-[9px] text-white/65 backdrop-blur-sm">Foto: {current.photographer} · Unsplash</span>}
  </section>;
}

function HomeFinder() {
  const catalog=useCatalog();
  const [category,setCategory]=useState(""); const [size,setSize]=useState(""); const [brand,setBrand]=useState(""); const [maxPrice,setMaxPrice]=useState("");
  const categoryProducts=matchingProducts(catalog,{category});
  const brandOptions=catalog.brands.filter(item=>categoryProducts.some(product=>product.brand_slug===item.slug));
  const sizeProducts=matchingProducts(catalog,{category,brand});
  const sizeOptions=catalog.sizes.map(item=>({...item,available:sizeProducts.filter(product=>product.sizes.includes(item.size||"")).length})).filter(item=>item.available>0);
  const sizeDisabled=sizeOptions.length===0;
  const priceProducts=matchingProducts(catalog,{category,brand,size}); const priceOptions=relevantPrices(priceProducts);
  const resultCount=matchingProducts(catalog,{category,brand,size,maxPrice}).length;
  const chooseCategory=(value:string)=>{setCategory(value);setBrand("");setSize("");setMaxPrice("");};
  const chooseBrand=(value:string)=>{setBrand(value);setSize("");setMaxPrice("");};
  const chooseSize=(value:string)=>{setSize(value);setMaxPrice("");};
  const params=new URLSearchParams(); if(category)params.set("category",category); if(size)params.set("size",size); if(brand)params.set("brand",brand); if(maxPrice)params.set("max_price",maxPrice);
  const href=`/capacetes${params.size?`?${params.toString()}`:""}`;
  return <section className="container-page relative z-10 -mt-2 rounded-b-[20px] border border-line bg-white p-5 md:-mt-4 md:p-6"><div className="grid gap-4 md:grid-cols-[repeat(4,1fr)_auto]">
    <label className="text-xs font-semibold">Tipo<select value={category} onChange={e=>chooseCategory(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted"><option value="">Todos os tipos</option>{catalog.categories.map(item=><option value={item.slug} key={item.slug}>{item.name} ({item.product_count})</option>)}</select></label>
    <label className="text-xs font-semibold">Marca<select value={brand} onChange={e=>chooseBrand(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted"><option value="">Todas as marcas ({categoryProducts.length})</option>{brandOptions.map(item=>{const count=categoryProducts.filter(product=>product.brand_slug===item.slug).length;return <option value={item.slug} key={item.slug}>{item.name} ({count})</option>;})}</select></label>
    <label className={`text-xs font-semibold ${sizeDisabled?"text-muted":""}`}>Tamanho<select disabled={sizeDisabled} value={sizeDisabled?"":size} onChange={e=>chooseSize(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60"><option value="">{sizeDisabled?"Não se aplica":"Todos os tamanhos"}</option>{sizeOptions.map(item=><option value={item.size} key={item.size}>{item.size} ({item.available})</option>)}</select></label>
    <label className="text-xs font-semibold">Preço<select disabled={priceOptions.length===0} value={maxPrice} onChange={e=>setMaxPrice(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60"><option value="">Qualquer preço ({priceProducts.length})</option>{priceOptions.map(item=><option value={item.limit} key={item.limit}>Até {item.limit.toLocaleString("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0})} ({item.count})</option>)}</select></label>
    <Button href={href} className="self-end">{catalog.filter_products.length?`Ver ${resultCount} ${resultCount===1?"produto":"produtos"}`:"Carregando…"}</Button>
  </div></section>;
}

function CatalogControls({basePath,catalog}:{basePath:string;catalog:CatalogData}) {
  const router=useRouter(); const searchParams=useSearchParams();
  const category=searchParams.get("category")||""; const brand=searchParams.get("brand")||""; const size=searchParams.get("size")||"";
  const sourceProducts=basePath==="/ofertas"?catalog.filter_products.filter(product=>product.featured):catalog.filter_products;
  const facetCatalog={...catalog,filter_products:sourceProducts};
  const categoryProducts=matchingProducts(facetCatalog,{category});
  const brandOptions=catalog.brands.filter(item=>categoryProducts.some(product=>product.brand_slug===item.slug));
  const sizeProducts=matchingProducts(facetCatalog,{category,brand});
  const sizeOptions=catalog.sizes.map(item=>({...item,available:sizeProducts.filter(product=>product.sizes.includes(item.size||"")).length})).filter(item=>item.available>0);
  const sizeDisabled=sizeOptions.length===0;
  const priceProducts=matchingProducts(facetCatalog,{category,brand,size}); const priceOptions=relevantPrices(priceProducts);
  const change=(key:string,value:string)=>{const next=new URLSearchParams(searchParams.toString());if(value)next.set(key,value);else next.delete(key);if(key==="category"){next.delete("brand");next.delete("size");next.delete("max_price");}if(key==="brand"){next.delete("size");next.delete("max_price");}if(key==="size")next.delete("max_price");router.push(`${basePath}${next.size?`?${next.toString()}`:""}`);};
  const selectClass="h-11 w-full rounded-xl border border-line bg-white px-3 text-sm text-muted";
  return <div className="mb-6 grid gap-3 rounded-2xl border border-line bg-white p-4 sm:grid-cols-2 lg:grid-cols-5">
    <select aria-label="Filtrar por categoria" value={category} onChange={e=>change("category",e.target.value)} className={selectClass}><option value="">Todas as categorias ({sourceProducts.length})</option>{catalog.categories.filter(item=>sourceProducts.some(product=>product.category_slug===item.slug)).map(item=>{const count=sourceProducts.filter(product=>product.category_slug===item.slug).length;return <option value={item.slug} key={item.slug}>{item.name} ({count})</option>;})}</select>
    <select aria-label="Filtrar por marca" value={brand} onChange={e=>change("brand",e.target.value)} className={selectClass}><option value="">Todas as marcas ({categoryProducts.length})</option>{brandOptions.map(item=>{const count=categoryProducts.filter(product=>product.brand_slug===item.slug).length;return <option value={item.slug} key={item.slug}>{item.name} ({count})</option>;})}</select>
    <select aria-label="Filtrar por tamanho" disabled={sizeDisabled} value={sizeDisabled?"":size} onChange={e=>change("size",e.target.value)} className={`${selectClass} disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60`}><option value="">{sizeDisabled?"Tamanho não aplicável":`Todos os tamanhos (${sizeProducts.length})`}</option>{sizeOptions.map(item=><option value={item.size} key={item.size}>{item.size} ({item.available})</option>)}</select>
    <select aria-label="Filtrar por preço" disabled={priceOptions.length===0} value={searchParams.get("max_price")||""} onChange={e=>change("max_price",e.target.value)} className={`${selectClass} disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60`}><option value="">Qualquer preço ({priceProducts.length})</option>{priceOptions.map(item=><option value={item.limit} key={item.limit}>Até {item.limit.toLocaleString("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0})} ({item.count})</option>)}</select>
    <select aria-label="Ordenar produtos" value={searchParams.get("sort")||""} onChange={e=>change("sort",e.target.value)} className={selectClass}><option value="">Mais relevantes</option><option value="price_asc">Menor preço</option><option value="price_desc">Maior preço</option><option value="rating">Melhor avaliados</option><option value="newest">Mais recentes</option></select>
    {searchParams.size>0&&<Link href={basePath} className="text-xs font-semibold text-accent sm:col-span-2 lg:col-span-5">Limpar filtros</Link>}
  </div>;
}

function resolveStorePage(path:string) {
  if (path === "/") return <HomePage/>;
  if (path === "/capacetes" || path === "/busca" || path === "/ofertas") return <CatalogPage path={path}/>;
  if (path.startsWith("/produto/")) return <ProductPage slug={path.split("/").pop()||""}/>;
  if (path === "/carrinho") return <CartPage/>;
  if (path === "/login") return <AuthPage/>;
  if (path === "/marcas" || path === "/marcas/ls2") return <BrandsPage detail={path.endsWith("ls2")}/>;
  if (path === "/comparar") return <ComparePage/>;
  if (path.startsWith("/conta")) return <AccountPage path={path}/>;
  if (["/sobre","/contato","/entrega","/garantia","/privacidade","/termos","/guia-de-tamanho","/ajuda","/ajuda/devolucoes"].includes(path)) return <ContentPage path={path}/>;
  if (path === "/mapa") return <RouteMapPage/>;
  return <NotFoundPage/>;
}

function HomePage() {
  const homeProducts=useApiProducts(8,"&featured=1");
  const catalog=useCatalog();
  return <>
    <HomeHero items={homeProducts}/>
    <HomeFinder/>
    <section className="container-page py-14 md:py-20"><SectionTitle title="Categorias" description="Todas as seções disponíveis no catálogo."/><div className="grid grid-cols-1 gap-3 sm:grid-cols-2 md:grid-cols-3">{catalog.categories.map((item,i)=><Link href={`/capacetes?category=${item.slug}`} className="group rounded-2xl bg-[#eef0f2] p-5 transition hover:bg-dark hover:text-white md:p-7" key={item.slug}><span className="text-xs font-bold text-accent">{String(i+1).padStart(2,"0")}</span><h3 className="mt-8 text-lg font-semibold">{item.name}</h3><p className="mt-2 text-xs text-muted group-hover:text-white/60">{item.product_count} produtos</p></Link>)}</div></section>
    <section className="container-page pb-16"><SectionTitle title="Mais vendidos" description="Os favoritos de quem pilota todos os dias." action={<Link href="/capacetes" className="hidden text-sm font-semibold md:block">Ver todos →</Link>}/><ProductGrid products={homeProducts.slice(0,4)}/></section>
    <section className="container-page mb-16 overflow-hidden rounded-[22px] bg-[#e9ecef] p-8 md:p-12"><div className="grid items-center gap-8 md:grid-cols-2"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-accent">Guia Ridekit</p><h2 className="mt-4 text-3xl font-semibold tracking-[-.04em] md:text-4xl">Proteção que acompanha seu ritmo.</h2><p className="mt-4 max-w-lg text-sm leading-6 text-muted">Descubra o tamanho, o tipo de casco e os recursos certos para o seu uso.</p><Button href="/guia-de-tamanho" variant="dark" className="mt-6">Ver guia de tamanho</Button></div><div className="h-56 rounded-2xl bg-[linear-gradient(135deg,#20242a,#0b0d10)] p-8 text-white"><Gauge className="text-accent" size={40}/><p className="mt-16 text-sm text-white/60">Cidade · Estrada · Aventura</p></div></div></section>
    <section className="container-page pb-16"><SectionTitle title="Marcas em destaque" description="Escolha por fabricante e encontre peças compatíveis."/><div className="grid grid-cols-3 gap-3 md:grid-cols-6">{["LS2","NORISK","ASX","AXXIS","KYT","SHOEI"].map(b=><Link href={b==="LS2"?"/marcas/ls2":"/marcas"} className="grid h-24 place-items-center rounded-2xl border border-line bg-white text-lg font-bold transition hover:border-ink" key={b}>{b}</Link>)}</div></section>
    <section className="container-page pb-16"><SectionTitle title="Lançamentos" description="Novos gráficos, materiais e tecnologias que acabaram de chegar."/><ProductGrid products={homeProducts.slice(4,8)}/></section>
    <section className="container-page pb-16"><SectionTitle title="Compra sem ruído" description="O básico bem feito antes, durante e depois do pedido."/><TrustStrip/></section>
  </>;
}

function CatalogPage({path}:{path:string}) {
  const offers=path==="/ofertas"; const searchParams=useSearchParams(); const catalog=useCatalog();
  const query=new URLSearchParams(searchParams.toString()); if(offers)query.set("featured","1");
  const apiProducts=useApiProducts(100,query.size?`&${query.toString()}`:"");
  const selectedCategory=catalog.categories.find(item=>item.slug===searchParams.get("category"));
  const title=offers?"Ofertas":selectedCategory?.name||"Todos os produtos";
  return <div className="container-page py-8 md:py-12"><p className="text-xs text-muted">Home / {title}</p><div className={`mt-5 rounded-[20px] ${offers?"bg-dark p-7 text-white md:p-10":"bg-white p-6"}`}><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">{apiProducts.length} produtos encontrados</p><h1 className="mt-3 text-3xl font-semibold tracking-[-.04em] md:text-4xl">{offers?"Ofertas que valem a viagem":title}</h1><p className={`mt-3 text-sm ${offers?"text-white/60":"text-muted"}`}>{offers?"Condições especiais em modelos selecionados.":selectedCategory?"Produtos desta categoria disponíveis no catálogo.":"Capacetes, acessórios e equipamentos de todas as categorias cadastradas."}</p></div><div className="mt-8"><CatalogControls basePath={path} catalog={catalog}/>{apiProducts.length?<ProductGrid products={apiProducts} compact/>:<div className="rounded-2xl border border-line bg-white p-10 text-center"><h2 className="text-lg font-semibold">Nenhum produto encontrado</h2><p className="mt-2 text-sm text-muted">Tente remover algum filtro.</p><Link href={path} className="mt-4 inline-block text-sm font-semibold text-accent">Limpar filtros</Link></div>}</div></div>;
}

type ProductDetailData={id:number;slug:string;name:string;sku:string;description:string;price_cents:number;compare_at_cents?:number;color:string;brand:string;category:string;category_slug:string;shell_material?:string;weight_grams?:number;solar_visor:number;pinlock_ready:number;images:{id:number;url:string;alt:string}[];variants:{id:number;sku:string;size:string;color:string;stock:number;reserved_stock:number;active:number}[]};

function ProductPage({slug}:{slug:string}) {
  const [product,setProduct]=useState<ProductDetailData|null>(null); const [variantId,setVariantId]=useState(0); const [image,setImage]=useState(""); const [quantity,setQuantity]=useState(1); const [added,setAdded]=useState(false); const [failed,setFailed]=useState(false);
  const {addToCart,toggleFavorite,isFavorite,busy}=useShop(); const recommendations=useApiProducts(4,product?`&category=${product.category_slug}`:"");
  useEffect(()=>{const controller=new AbortController();setProduct(null);setFailed(false);fetch(`/api/products/${slug}`,{signal:controller.signal}).then(r=>r.ok?r.json():Promise.reject(new Error("Produto não encontrado"))).then(({data})=>{setProduct(data);const available=data.variants.find((variant:ProductDetailData["variants"][number])=>variant.active&&variant.stock>variant.reserved_stock);setVariantId(available?.id||0);setImage(data.images[0]?.url||"");}).catch(error=>{if(error?.name!=="AbortError")setFailed(true);});return()=>controller.abort();},[slug]);
  if(failed)return <div className="container-page py-20 text-center"><h1 className="text-2xl font-semibold">Produto não encontrado</h1><Button href="/capacetes" className="mt-5">Voltar ao catálogo</Button></div>;
  if(!product)return <div className="container-page py-20 text-sm text-muted">Carregando produto…</div>;
  const selected=product.variants.find(variant=>variant.id===variantId); const availableVariants=product.variants.filter(variant=>variant.active&&variant.stock>variant.reserved_stock); const hasSizes=availableVariants.some(variant=>variant.size!=="Único"); const favorite=isFavorite(product.id);
  const add=async()=>{if(!variantId)return;const ok=await addToCart(variantId,quantity);setAdded(ok);};
  return <div className="container-page py-7 md:py-10"><p className="mb-6 text-xs text-muted">Home / {product.category} / {product.name}</p><section className="grid gap-8 lg:grid-cols-[1.08fr_.92fr]"><div className="grid gap-3 md:grid-cols-[86px_1fr]"><div className="order-2 flex gap-2 overflow-x-auto md:order-1 md:flex-col">{product.images.map(item=><button onClick={()=>setImage(item.url)} key={item.id} className={`w-[72px] shrink-0 rounded-[14px] border ${image===item.url?"border-accent":"border-line"}`}><ProductVisual image={item.url} className="aspect-square w-full"/></button>)}</div><ProductVisual image={image} className="order-1 aspect-square md:order-2"/></div><div className="lg:pl-8"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold tracking-[.18em] text-muted">{product.brand}</p><h1 className="mt-3 text-3xl font-semibold tracking-[-.04em] md:text-4xl">{product.name}</h1></div><button disabled={busy} onClick={()=>toggleFavorite(product.id)} aria-label={favorite?"Remover dos favoritos":"Adicionar aos favoritos"} className={`focus-ring grid size-11 shrink-0 place-items-center rounded-xl border ${favorite?"border-accent bg-accent-soft text-accent":"border-line bg-white text-muted"}`}><Heart size={19} className={favorite?"fill-current":""}/></button></div><div className="mt-4"><Rating/></div><div className="mt-7 flex items-baseline gap-3">{product.compare_at_cents&&<s className="text-sm text-muted">{money(product.compare_at_cents)}</s>}<p className="text-3xl font-semibold">{money(product.price_cents)}</p></div><p className="mt-2 text-sm text-muted">10x de {money(Math.ceil(product.price_cents/10))} sem juros · 5% de desconto no Pix</p><div className="my-7 border-t border-line"/><div><div className="flex justify-between"><b className="text-sm">Cor: {product.color}</b><span className="text-xs text-muted">Cód. {product.sku}</span></div></div>{hasSizes&&<div className="mt-7"><div className="flex justify-between"><b className="text-sm">Tamanho</b><Link href="/guia-de-tamanho" className="text-xs font-semibold underline">Guia de tamanho</Link></div><div className="mt-3 flex flex-wrap gap-2">{availableVariants.map(variant=><button onClick={()=>{setVariantId(variant.id);setAdded(false);}} key={variant.id} className={`h-11 min-w-14 rounded-xl border px-3 text-sm font-semibold ${variantId===variant.id?"border-dark bg-dark text-white":"border-line bg-white"}`}>{variant.size.replace(" / ","/")}</button>)}</div></div>}<label className="mt-6 block text-xs font-semibold">Calcular frete<div className="mt-2 flex gap-2"><input className="h-12 min-w-0 flex-1 rounded-xl border border-line px-4 text-sm" placeholder="00000-000"/><Button variant="outline">Calcular</Button></div></label><div className="mt-6 flex gap-3"><Quantity value={quantity} onChange={setQuantity} max={Math.min(10,selected?selected.stock-selected.reserved_stock:1)}/><Button className="flex-1" onClick={add}>{busy?"Adicionando…":added?<><Check size={18}/> Adicionado ao carrinho</>:<><ShoppingBag size={18}/> Adicionar ao carrinho</>}</Button></div><div className="mt-7 grid gap-3"><CheckLine>Produto original com nota fiscal</CheckLine><CheckLine>Troca facilitada em até 7 dias</CheckLine><CheckLine>Pagamento protegido</CheckLine></div></div></section>
    <section className="py-16"><SectionTitle title="Especificações técnicas" description="Dados cadastrados para este produto."/><div className="grid gap-3 md:grid-cols-4">{[["Material",product.shell_material||"Não informado"],["Peso",product.weight_grams?`${product.weight_grams} g`:"Não informado"],["Viseira solar",product.solar_visor?"Sim":"Não"],["Pinlock",product.pinlock_ready?"Preparado":"Não informado"]].map(([title,value])=><div className="card p-5" key={title}><b>{title}</b><p className="mt-3 text-xs leading-6 text-muted">{value}</p></div>)}</div></section><section className="pb-16"><SectionTitle title="Você também pode gostar"/><ProductGrid products={recommendations.filter(item=>item.slug!==product.slug).slice(0,4)} compact/></section></div>;
}

function CartPage() { const {cart,loading,busy,updateCartItem,removeCartItem}=useShop();if(loading)return <div className="container-page py-20 text-sm text-muted">Carregando carrinho…</div>;if(!cart.items.length)return <div className="container-page py-16 text-center"><ShoppingBag className="mx-auto text-muted" size={38}/><h1 className="mt-5 text-3xl font-semibold">Seu carrinho está vazio</h1><p className="mt-3 text-sm text-muted">Encontre o equipamento certo e adicione ao carrinho.</p><Button href="/capacetes" className="mt-6">Ver produtos</Button></div>;return <div className="container-page py-10"><SectionTitle title="Seu carrinho" description={`${cart.summary.items} ${cart.summary.items===1?"item":"itens"} no carrinho.`}/><div className="grid gap-7 lg:grid-cols-[1fr_380px]"><div className="grid gap-4">{cart.items.map(item=><div className="card flex gap-4 p-4 md:p-5" key={item.id}><ProductVisual image={item.image_url} className="size-28 shrink-0 md:size-36"/><div className="min-w-0 flex-1"><p className="text-xs font-semibold text-muted">{item.brand}</p><Link href={`/produto/${item.slug}`} className="mt-1 block font-semibold hover:text-accent">{item.name}</Link><p className="mt-2 text-xs text-muted">{item.color} · {item.size}</p><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><Quantity value={item.quantity} onChange={value=>updateCartItem(item.id,value)} max={10}/><div className="flex items-center gap-4"><b>{money(item.total_cents)}</b><button disabled={busy} onClick={()=>removeCartItem(item.id)} className="text-xs font-semibold text-danger">Remover</button></div></div></div></div>)}</div><OrderSummary action="Continuar compra" href="/checkout" summary={cart.summary}/></div></div>; }

function OrderSummary({action,href,summary}:{action:string;href:string;summary?:CartSummary}) { const subtotal=summary?.subtotal_cents??96980;const shipping=summary?.shipping_cents??0;const total=summary?.total_cents??96980;return <aside className="card h-fit p-5 md:p-6"><h2 className="text-lg font-semibold">Resumo do pedido</h2><div className="mt-5 grid gap-3 text-sm text-muted"><div className="flex justify-between"><span>Subtotal</span><span>{money(subtotal)}</span></div><div className="flex justify-between"><span>Frete</span>{shipping?<span>{money(shipping)}</span>:<b className="text-success">Grátis</b>}</div><div className="border-t border-line pt-4 text-ink"><div className="flex justify-between"><b>Total</b><b className="text-xl">{money(total)}</b></div><p className="mt-1 text-right text-xs text-muted">ou 10x de {money(Math.ceil(total/10))}</p></div></div><Button href={href} className="mt-6 w-full">{action} <ArrowRight size={17}/></Button><div className="mt-5 flex items-center justify-center gap-2 text-xs text-muted"><LockKeyhole size={14}/> Compra segura</div></aside>; }

function CheckoutPage({path}:{path:string}) {
  const steps=["Carrinho","Identificação","Endereço","Entrega","Pagamento"];
  const routes=["/checkout","/checkout/identificacao","/checkout/endereco","/checkout/entrega","/checkout/pagamento"];
  const special=path.split("/").pop()||""; let active=Math.max(0,routes.indexOf(path)); if(["pix","erro","sucesso"].includes(special))active=4;
  return <main className="min-h-screen bg-canvas"><header className="border-b border-line bg-white"><div className="container-page flex h-20 items-center justify-between"><Link href="/" className="text-xl font-bold">RIDEKIT</Link><span className="text-sm font-medium text-muted">Checkout seguro</span><span className="hidden items-center gap-2 text-xs text-muted md:flex"><ShieldCheck size={16}/> Compra protegida</span></div></header><div className="container-page py-6 md:py-8"><div className="hide-scrollbar flex gap-2 overflow-x-auto pb-2">{steps.map((s,i)=><div className={`flex min-w-fit items-center gap-2 rounded-xl px-3 py-3 text-xs font-medium md:flex-1 ${i<=active?"bg-dark text-white":"bg-white text-muted"}`} key={s}><span className={`grid size-5 place-items-center rounded-full text-[10px] ${i<active?"bg-success":"bg-white/15"}`}>{i<active?<Check size={12}/>:i+1}</span>{s}</div>)}</div><CheckoutContent step={special} path={path} routes={routes} active={active}/><div className="mt-5 grid grid-cols-2 gap-3 text-center text-xs text-muted md:grid-cols-5">{["Compra segura","Produto original","Nota fiscal","Troca facilitada","Atendimento humano"].map(x=><div className="rounded-xl bg-white p-4" key={x}>{x}</div>)}</div></div></main>;
}

function CheckoutContent({step,path,routes,active}:{step:string;path:string;routes:string[];active:number}) {
  const {cart}=useShop();
  if(step==="pix")return <CheckoutStatus type="pix"/>; if(step==="erro")return <CheckoutStatus type="erro"/>; if(step==="sucesso")return <CheckoutStatus type="sucesso"/>;
  const title={checkout:"Revise seu carrinho",identificacao:"Identificação",endereco:"Endereço de entrega",entrega:"Escolha a entrega",pagamento:"Escolha como pagar"}[step||"checkout"];
  return <><h1 className="mt-8 text-3xl font-semibold tracking-[-.04em]">{title}</h1><div className="mt-6 grid gap-7 lg:grid-cols-[1fr_390px]"><section className="card p-5 md:p-6">{step==="checkout"?<div className="grid gap-4">{cart.items.map(item=><div className="flex gap-4 border-b border-line pb-4 last:border-0" key={item.id}><ProductVisual image={item.image_url} className="size-24 shrink-0"/><div><b>{item.name}</b><p className="mt-1 text-xs text-muted">{item.color} · {item.size} · Qtd. {item.quantity}</p><p className="mt-3 font-semibold">{money(item.total_cents)}</p></div></div>)}</div>:step==="entrega"?<Options options={[["Entrega econômica","3 a 5 dias úteis · Grátis"],["Entrega expressa","1 a 2 dias úteis · R$ 29,90"],["Retirada","Disponível hoje · Grátis"]]}/>:step==="pagamento"?<><Options options={[["Pix · 5% OFF","Aprovação em poucos segundos"],["Cartão de crédito","Até 10x sem juros"],["2 cartões","Divida o valor entre dois cartões"]]}/><div className="mt-6 grid gap-4 md:grid-cols-2"><Field label="Número do cartão" placeholder="0000 0000 0000 0000" wide/><Field label="Validade" placeholder="MM/AA"/><Field label="CVV" placeholder="123"/><Field label="Parcelas" placeholder={`10x de ${money(Math.ceil(cart.summary.total_cents/10))}`} wide/></div></>:<FormFields type={step}/>}</section><OrderSummary action={step==="pagamento"?`Pagar ${money(cart.summary.total_cents)}`:"Continuar"} href={step==="pagamento"?"/checkout/sucesso":routes[Math.min(active+1,4)]} summary={cart.summary}/></div></>;
}
function FormFields({type}:{type:string}) { const fields=type==="identificacao"?[["E-mail","voce@email.com"],["CPF","000.000.000-00"],["Telefone","(00) 00000-0000"]]:[["CEP","00000-000"],["Endereço","Rua, avenida..."],["Número","123"],["Complemento","Apto, bloco..."],["Bairro","Seu bairro"],["Cidade / UF","São Paulo / SP"]]; return <div className="grid gap-4 md:grid-cols-2">{fields.map(([l,p],i)=><Field label={l} placeholder={p} wide={i<2} key={l}/>)}</div>; }
function Field({label,placeholder,wide=false}:{label:string;placeholder:string;wide?:boolean}) { return <label className={`text-xs font-semibold ${wide?"md:col-span-2":""}`}>{label}<input className="mt-2 h-12 w-full rounded-xl border border-line px-4 text-sm font-normal outline-none focus:border-accent" placeholder={placeholder}/></label>; }
function Options({options}:{options:string[][]}) { const [pick,setPick]=useState(0); return <div className="grid gap-3">{options.map(([t,d],i)=><button onClick={()=>setPick(i)} className={`flex items-center gap-4 rounded-xl border p-4 text-left ${pick===i?"border-accent bg-accent-soft":"border-line"}`} key={t}><span className={`size-4 rounded-full border-4 ${pick===i?"border-accent":"border-line"}`}/><span><b className="text-sm">{t}</b><small className="mt-1 block text-muted">{d}</small></span></button>)}</div>; }
function CheckoutStatus({type}:{type:"pix"|"erro"|"sucesso"}) { const cfg=type==="pix"?["Pagamento via Pix","Escaneie o QR Code ou copie o código. Seu pedido será confirmado assim que o pagamento for aprovado.","Aguardando pagamento"]:type==="erro"?["Não foi possível processar o cartão","Revise os dados ou escolha outra forma de pagamento.","Tentar novamente"]:["Pedido confirmado!","Tudo certo. Enviamos os detalhes para o seu e-mail.","Acompanhar pedido"]; return <section className="mx-auto mt-10 max-w-2xl rounded-3xl border border-line bg-white p-7 text-center md:p-12"><div className={`mx-auto grid size-16 place-items-center rounded-full ${type==="erro"?"bg-red-50 text-danger":type==="pix"?"bg-orange-50 text-accent":"bg-green-50 text-success"}`}>{type==="erro"?<CircleAlert/>:type==="pix"?<Copy/>:<Check/>}</div><h1 className="mt-6 text-3xl font-semibold">{cfg[0]}</h1><p className="mx-auto mt-3 max-w-lg text-sm leading-6 text-muted">{cfg[1]}</p>{type==="pix"&&<div className="mx-auto mt-7 grid size-48 place-items-center bg-[repeating-linear-gradient(45deg,#111_0_5px,#fff_5px_10px)]"><span className="bg-white p-3 text-xs font-bold">PIX</span></div>}<Button href={type==="sucesso"?"/conta/pedidos/10234":type==="erro"?"/checkout/pagamento":"/checkout/pix"} className="mt-7">{cfg[2]}</Button></section>; }

function AuthPage() { return <div className="container-page py-12"><div className="mx-auto grid max-w-4xl overflow-hidden rounded-3xl border border-line bg-white md:grid-cols-2"><div className="bg-dark p-8 text-white md:p-12"><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Sua garagem Ridekit</p><h1 className="mt-6 text-4xl font-semibold tracking-[-.04em]">Acompanhe tudo sem ruído.</h1><p className="mt-4 text-sm leading-6 text-white/60">Pedidos, favoritos, endereços e suporte em um só lugar.</p></div><form className="p-8 md:p-12"><h2 className="text-2xl font-semibold">Entrar</h2><div className="mt-6 grid gap-4"><Field label="E-mail" placeholder="voce@email.com" wide/><Field label="Senha" placeholder="Sua senha" wide/></div><Button href="/conta" className="mt-6 w-full">Continuar</Button><p className="mt-6 text-center text-xs text-muted">Ainda não tem conta? <b className="text-ink">Cadastre-se</b></p></form></div></div>; }

function BrandsPage({detail}:{detail:boolean}) { return <div className="container-page py-10">{detail?<><section className="grid overflow-hidden rounded-3xl bg-dark text-white md:grid-cols-2"><div className="p-8 md:p-12"><p className="text-xs font-bold tracking-[.2em] text-accent">LS2 HELMETS</p><h1 className="mt-5 text-5xl font-semibold tracking-[-.05em]">Performance global. Escolha precisa.</h1><p className="mt-5 text-sm leading-6 text-white/60">Capacetes para cada estilo de pilotagem, com tecnologia, conforto e segurança.</p><Button href="/capacetes" className="mt-7">Ver coleção</Button></div><div className="min-h-72 bg-[#24272d] p-10"><ProductVisual className="h-full !bg-transparent"/></div></section><section className="py-14"><SectionTitle title="Famílias em destaque"/><div className="grid grid-cols-2 gap-3 md:grid-cols-5">{["FF358","Stream II","Vector II","Advant","MX701"].map(x=><div className="card p-6 font-semibold" key={x}>{x}</div>)}</div></section><SectionTitle title="Mais vendidos da LS2"/><ProductGrid products={products.filter(p=>p.brand==="LS2").concat(products.slice(0,2))}/></>:<><SectionTitle title="Marcas" description="Fabricantes selecionados pela Ridekit."/><div className="grid grid-cols-2 gap-4 md:grid-cols-4">{["LS2","NORISK","ASX","AXXIS","KYT","SHOEI","AGV","BELL"].map(b=><Link href={b==="LS2"?"/marcas/ls2":"/capacetes"} className="grid h-40 place-items-center rounded-2xl border border-line bg-white text-2xl font-bold hover:border-ink" key={b}>{b}</Link>)}</div></>}</div>; }

function ComparePage() { return <div className="container-page py-10"><SectionTitle title="Comparar capacetes" description="Compare os pontos que realmente mudam sua escolha."/><div className="overflow-x-auto rounded-2xl border border-line bg-white"><table className="w-full min-w-[760px] text-left text-sm"><thead><tr>{["Característica","LS2 FF358 Pro","Norisk Razor","LS2 Stream II"].map(x=><th className="border-b border-line p-5" key={x}>{x}</th>)}</tr></thead><tbody>{[["Preço","R$ 899,90","R$ 749,90","R$ 1.299,90"],["Casco","HPTT","ABS","KPA"],["Peso","1.500 g","1.480 g","1.550 g"],["Viseira solar","Não","Não","Sim"],["Pinlock","Preparado","Preparado","Incluso"]].map(r=><tr key={r[0]}>{r.map((x,i)=><td className={`border-b border-line p-5 ${i===0?"font-semibold":"text-muted"}`} key={x}>{x}</td>)}</tr>)}</tbody></table></div></div>; }

function AccountPage({path}:{path:string}) { const section=path.includes("favoritos")?"Favoritos":path.includes("enderecos")?"Endereços":path.includes("pedidos/10234")?"Pedido #10234":path.includes("pedidos")?"Meus pedidos":"Visão geral"; return <div className="container-page py-10"><div className="grid gap-7 lg:grid-cols-[240px_1fr]"><AccountNav/><section><SectionTitle title={section} description={section==="Meus pedidos"?"Acompanhe compra, pagamento e entrega.":section==="Favoritos"?"Produtos que você salvou para consultar depois.":"Tudo da sua conta em um só lugar."}/>{section==="Favoritos"?<FavoritesPage/>:section==="Endereços"?<div className="grid gap-4 md:grid-cols-2"><Address/><Address/><Button variant="outline" className="min-h-40">+ Adicionar endereço</Button></div>:section==="Pedido #10234"?<OrderDetail/>:section==="Meus pedidos"?<Orders/>:<AccountOverview/>}</section></div></div>; }
function FavoritesPage(){const {favorites,loading}=useShop();if(loading)return <p className="text-sm text-muted">Carregando favoritos…</p>;if(!favorites.length)return <div className="rounded-2xl border border-line bg-white p-10 text-center"><Heart className="mx-auto text-muted" size={34}/><h2 className="mt-4 text-xl font-semibold">Nenhum favorito ainda</h2><p className="mt-2 text-sm text-muted">Use o coração nos produtos para guardar suas escolhas.</p><Button href="/capacetes" className="mt-6">Explorar produtos</Button></div>;const items:Product[]=favorites.map(item=>({id:item.id,slug:item.slug,brand:item.brand,name:item.name,price:money(item.price_cents),oldPrice:item.compare_at_cents?money(item.compare_at_cents):undefined,tone:"from-zinc-950 to-zinc-700",tag:item.featured?"DESTAQUE":undefined,image:item.image_url,photographer:item.photographer,category:item.category,sizes:item.sizes_csv?item.sizes_csv.split("|"):[]}));return <ProductGrid products={items} compact/>;}
function AccountNav() { return <aside className="card h-fit p-3"><p className="px-3 py-3 text-xs font-bold uppercase tracking-widest text-muted">Minha conta</p>{[["Visão geral","/conta"],["Pedidos","/conta/pedidos"],["Favoritos","/conta/favoritos"],["Endereços","/conta/enderecos"],["Dados pessoais","/conta"],["Cupons","/conta"],["Ajuda","/ajuda"],["Sair","/"]].map(([n,h])=><Link href={h} className="flex items-center justify-between rounded-xl px-3 py-3 text-sm font-medium hover:bg-canvas" key={n}>{n}<ChevronRight size={15}/></Link>)}</aside>; }
function Orders() { return <div className="grid gap-4">{[["#10234","Enviado","29 ago 2026 · R$ 969,80"],["#10198","Entregue","10 ago 2026 · R$ 699,90"],["#10072","Cancelado","14 jul 2026 · R$ 149,90"]].map(([id,s,d])=><Link href="/conta/pedidos/10234" className="card flex items-center gap-4 p-5" key={id}><ProductVisual className="size-20 shrink-0"/><div className="flex-1"><div className="flex justify-between"><b>{id}</b><span className="rounded-full bg-green-50 px-3 py-1 text-[10px] font-bold text-success">{s}</span></div><p className="mt-2 text-xs text-muted">{d}</p><p className="mt-1 text-sm">LS2 FF358 Pro · Preto · 58/M</p></div></Link>)}</div>; }
function OrderDetail() { return <div className="grid gap-5"><div className="card p-6"><div className="flex items-center justify-between"><b>Status do pedido</b><span className="rounded-full bg-green-50 px-3 py-1 text-xs font-bold text-success">Enviado</span></div><div className="mt-8 grid grid-cols-4 gap-2">{["Pedido recebido","Pagamento aprovado","Em transporte","Entregue"].map((x,i)=><div key={x}><div className={`h-2 rounded-full ${i<3?"bg-success":"bg-line"}`}/><p className="mt-3 text-[11px] text-muted">{x}</p></div>)}</div></div><div className="card p-6"><b>Itens do pedido</b><div className="mt-5 flex gap-4"><ProductVisual className="size-24"/><div><b>LS2 FF358 Pro Mono</b><p className="mt-2 text-xs text-muted">Preto · 58/M · Qtd. 1</p><p className="mt-3 font-semibold">R$ 899,90</p></div></div></div></div>; }
function Address() { return <div className="card p-5"><MapPin className="text-accent"/><b className="mt-4 block">Casa</b><p className="mt-2 text-sm leading-6 text-muted">Rua das Pilotas, 123<br/>São Paulo — SP · 00000-000</p><Button variant="ghost" className="mt-4 px-0">Editar</Button></div>; }
function AccountOverview() { const {favorites}=useShop();return <div className="grid gap-4 md:grid-cols-3"><div className="card p-5"><Package className="text-accent"/><b className="mt-4 block">3 pedidos</b><p className="mt-2 text-xs text-muted">1 em transporte</p></div><Link href="/conta/favoritos" className="card p-5"><Heart className="text-accent"/><b className="mt-4 block">{favorites.length} {favorites.length===1?"favorito":"favoritos"}</b><p className="mt-2 text-xs text-muted">Produtos salvos</p></Link><div className="card p-5"><MapPin className="text-accent"/><b className="mt-4 block">2 endereços</b><p className="mt-2 text-xs text-muted">Entrega mais rápida</p></div></div>; }

const content:Record<string,{title:string;intro:string;sections:string[][]}>={
  "/sobre":{title:"Sobre a Ridekit",intro:"Uma loja feita para quem quer equipamento certo, informação clara e compra sem atrito.",sections:[["Nossa proposta","Curadoria de capacetes, equipamentos e acessórios com foco em segurança, compatibilidade e confiança."],["Clareza","Preço, tamanho, estoque e prazo sem letras miúdas."],["Especialização","Conteúdo e filtros pensados para motociclistas."],["Pós-compra","Acompanhamento, troca e suporte bem resolvidos."]]},
  "/entrega":{title:"Frete e entrega",intro:"Prazos claros e acompanhamento em cada etapa.",sections:[["Entrega econômica","A melhor relação de prazo e custo para todo o Brasil."],["Entrega expressa","Para quando o próximo caminho não pode esperar."],["Rastreamento","Atualizações do despacho até a sua porta."]]},
  "/garantia":{title:"Garantia e segurança",intro:"Produto original, nota fiscal e compra protegida.",sections:[["Procedência","Trabalhamos com fabricantes e distribuidores homologados."],["Garantia","Cobertura conforme cada fabricante e suporte Ridekit."],["Pagamento protegido","Ambiente seguro para Pix e cartão."]]},
  "/privacidade":{title:"Política de privacidade",intro:"Como coletamos, usamos e protegemos seus dados.",sections:[["Dados coletados","Usamos apenas as informações necessárias para sua compra e atendimento."],["Seus direitos","Você pode consultar, corrigir ou solicitar a exclusão de dados."],["Segurança","Aplicamos controles técnicos e organizacionais de proteção."]]},
  "/termos":{title:"Termos de uso",intro:"Condições para uma relação clara entre você e a Ridekit.",sections:[["Uso da plataforma","Navegação e compra devem seguir as condições apresentadas."],["Preços e disponibilidade","Estoque e valores podem mudar até a confirmação do pedido."],["Responsabilidades","Cada etapa é comunicada com transparência."]]},
  "/guia-de-tamanho":{title:"Guia de tamanho",intro:"O capacete certo deve ficar firme, uniforme e confortável.",sections:[["1. Meça a cabeça","Passe a fita métrica acima das sobrancelhas, contornando a parte mais larga."],["2. Compare a medida","56 cm costuma equivaler a S; 58 a M; 60 a L; 62 a XL."],["3. Confira o ajuste","O capacete novo fica justo e cede levemente com o uso."]]},
  "/ajuda":{title:"Central de ajuda",intro:"Respostas rápidas para comprar e acompanhar sem ruído.",sections:[["Pedidos e entrega","Acompanhe status, nota fiscal e rastreamento."],["Trocas e devoluções","Veja prazos e prepare sua solicitação."],["Produto e tamanho","Encontre compatibilidade e o ajuste correto."],["Pagamento","Tire dúvidas sobre Pix, cartão e estorno."]]},
  "/ajuda/devolucoes":{title:"Trocas e devoluções",intro:"Um processo simples do pedido à resolução.",sections:[["Prazo","Solicite a devolução em até 7 dias após o recebimento."],["Condição do produto","Envie o item sem sinais de uso e com embalagem e acessórios."],["Reembolso","Após análise, o valor retorna pelo mesmo meio de pagamento."]]},
};
function ContentPage({path}:{path:string}) { if(path==="/contato")return <ContactPage/>; const c=content[path]; return <div><section className="bg-dark py-14 text-white md:py-20"><div className="container-page"><p className="text-xs font-bold uppercase tracking-[.2em] text-accent">Ridekit · Informação</p><h1 className="mt-5 max-w-4xl text-4xl font-semibold tracking-[-.05em] md:text-5xl">{c.title}</h1><p className="mt-5 max-w-2xl text-base leading-7 text-white/60">{c.intro}</p></div></section><section className="container-page grid gap-4 py-12 md:grid-cols-2 md:py-16">{c.sections.map(([t,d])=><article className="card p-6 md:p-8" key={t}><h2 className="text-xl font-semibold">{t}</h2><p className="mt-4 text-sm leading-7 text-muted">{d}</p></article>)}</section></div>; }
function ContactPage() { return <div className="container-page py-10 md:py-14"><SectionTitle title="Fale com a Ridekit" description="Dúvida sobre produto, tamanho ou pedido? A gente resolve."/><div className="grid gap-7 lg:grid-cols-[1fr_360px]"><form className="card grid gap-4 p-6 md:grid-cols-2"><Field label="Nome" placeholder="Seu nome"/><Field label="E-mail" placeholder="voce@email.com"/><Field label="Assunto" placeholder="Como podemos ajudar?" wide/><label className="text-xs font-semibold md:col-span-2">Mensagem<textarea className="mt-2 h-40 w-full resize-none rounded-xl border border-line p-4 text-sm font-normal" placeholder="Conte pra gente..."/></label><Button className="md:col-span-2">Enviar mensagem</Button></form><div className="grid gap-3">{[["WhatsApp","Seg–sex · 9h às 18h"],["E-mail","ajuda@ridekit.com.br"],["Pedidos","Acompanhe pela sua conta"]].map(([t,d])=><div className="card p-5" key={t}><b>{t}</b><p className="mt-2 text-sm text-muted">{d}</p></div>)}</div></div></div>; }

function RouteMapPage() { return <div className="container-page py-10"><SectionTitle title="Mapa do projeto" description="Rotas implementadas a partir do sitemap e das telas do Figma."/><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{routeMap.map(([href,name])=><Link className="card flex items-center justify-between p-4 text-sm hover:border-ink" href={href} key={href}><span><b>{name}</b><small className="mt-1 block text-muted">{href}</small></span><ChevronRight size={16}/></Link>)}</div></div>; }
function NotFoundPage() { return <section className="container-page py-24 text-center"><p className="text-8xl font-semibold text-accent">404</p><h1 className="mt-5 text-3xl font-semibold">Essa rota saiu da pista.</h1><p className="mt-3 text-sm text-muted">Volte para a loja e encontre o equipamento certo.</p><Button href="/" className="mt-7">Voltar para a home</Button></section>; }

function AdminPage({path}:{path:string}) { const label=path==="/admin"?"Dashboard":path.includes("produtos/editar")?"Editar produto":path.split("/").pop()!.replace(/^./,c=>c.toUpperCase()); return <div className="min-h-screen bg-canvas md:flex"><AdminNav active={label}/><main className="min-w-0 flex-1 p-5 md:p-8"><div className="flex items-center justify-between"><div><p className="text-xs text-muted">RIDEKIT ADMIN</p><h1 className="mt-2 text-3xl font-semibold tracking-[-.04em]">{label}</h1></div><Button>{label==="Produtos"?"Novo produto":"Exportar"}</Button></div>{path==="/admin"?<Dashboard/>:path.includes("editar")?<AdminEdit/>:<AdminTable label={label}/>}</main></div>; }
function AdminNav({active}:{active:string}) { const icons=[LayoutDashboard,Package,Tags,Tags,Warehouse,ShoppingBag,Users,Tags,Star,Settings]; return <aside className="w-full bg-dark p-4 text-white md:min-h-screen md:w-[230px] md:p-[18px]"><Link href="/admin" className="text-xl font-bold">RIDEKIT <span className="text-xs text-accent">ADMIN</span></Link><nav className="mt-7 flex gap-1 overflow-x-auto md:grid">{adminSections.map((n,i)=>{const Icon=icons[i];const h=n==="Dashboard"?"/admin":`/admin/${n.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"")}`;return <Link className={`flex min-w-fit items-center gap-3 rounded-xl px-3 py-3 text-[13px] ${active.toLowerCase().includes(n.toLowerCase())?"bg-[#20242a] text-white":"text-[#b9c0c9] hover:bg-white/5"}`} href={h} key={n}><Icon size={17}/>{n}</Link>})}</nav></aside>; }
function Dashboard() { return <div className="mt-7"><p className="text-sm text-muted">Visão geral da operação e das vendas.</p><div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Vendas hoje","R$ 12.430","+12,4%"],["Pedidos","32","+8,2%"],["Ticket médio","R$ 388","+3,1%"],["Sem estoque","12","Atenção"]].map(([t,v,d])=><div className="card p-5" key={t}><p className="text-xs font-medium text-muted">{t}</p><p className="mt-3 text-3xl font-semibold">{v}</p><p className={`mt-2 text-xs ${d==="Atenção"?"text-danger":"text-success"}`}>{d}</p></div>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><div className="card p-6"><div className="flex justify-between"><b>Receita · últimos 30 dias</b><b>R$ 184.320</b></div><div className="mt-10 flex h-64 items-end gap-3">{[35,48,42,70,58,82,76,92,68,88,96,86].map((h,i)=><div className="flex-1 rounded-t bg-dark/90 hover:bg-accent" style={{height:`${h}%`}} key={i}/>)}</div></div><AdminTable label="Pedidos recentes" compact/></div></div>; }
function AdminTable({label,compact=false}:{label:string;compact?:boolean}) { return <div className={`${compact?"":"mt-7"} card overflow-hidden`}><div className="flex items-center justify-between border-b border-line p-5"><b>{label}</b><div className="flex items-center gap-2 rounded-xl bg-canvas px-3"><Search size={15}/><input className="h-10 bg-transparent text-xs outline-none" placeholder="Buscar..."/></div></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-xs"><thead className="bg-canvas text-muted"><tr>{["ID / SKU","Nome","Valor","Status","Atualizado"].map(x=><th className="p-4 font-medium" key={x}>{x}</th>)}</tr></thead><tbody>{[["#10234","LS2 FF358 Pro","R$ 899,90","Enviado","Hoje, 14:32"],["#10233","Norisk Razor","R$ 749,90","Preparando","Hoje, 13:18"],["#10232","LS2 Stream II","R$ 1.299,90","Pago","Hoje, 11:02"],["#10231","ASX City","R$ 559,90","Sem estoque","Ontem, 18:45"]].map(r=><tr className="border-t border-line" key={r[0]}>{r.map((x,i)=><td className={`p-4 ${i===1?"font-semibold":""}`} key={x}>{i===3?<span className="rounded-full bg-orange-50 px-2.5 py-1 text-[10px] font-bold text-accent">{x}</span>:x}</td>)}</tr>)}</tbody></table></div></div>; }
function AdminEdit() { return <form className="mt-7 grid gap-6 xl:grid-cols-[1fr_340px]"><div className="card grid gap-5 p-6 md:grid-cols-2"><Field label="Nome do produto" placeholder="LS2 FF358 Pro Mono" wide/><Field label="Marca" placeholder="LS2"/><Field label="Categoria" placeholder="Capacete fechado"/><Field label="Preço" placeholder="R$ 899,90"/><Field label="Preço promocional" placeholder="R$ 849,90"/><label className="text-xs font-semibold md:col-span-2">Descrição<textarea className="mt-2 h-36 w-full rounded-xl border border-line p-4 font-normal" defaultValue="Capacete integral com casco HPTT e forro removível."/></label></div><aside className="grid h-fit gap-5"><div className="card p-5"><b>Publicação</b><p className="mt-3 text-xs text-success">● Produto ativo</p><Button className="mt-5 w-full">Salvar alterações</Button></div><div className="card p-5"><b>Imagem principal</b><ProductVisual className="mt-4 aspect-square"/></div></aside></form>; }
